"""Mandelbrot escape times computed on the GPU, summarized on standard output.

Usage: uv run main.py <parameter-file>

The parameter file holds two lines:

    <width> <height> <limit>
    <x_min> <x_max> <y_min> <y_max>
"""

import math
import sys

import numpy as np
import wgpu

WORKGROUP_SIZE = 64

# Uniform block read by the kernel. Layout matches the WGSL struct below:
# three u32 counts, one u32 pad, then four f32 values (32 bytes total).
PARAMS_DTYPE = np.dtype(
    [
        ("width", np.uint32),
        ("height", np.uint32),
        ("limit", np.uint32),
        ("pad", np.uint32),
        ("x_min", np.float32),
        ("dx", np.float32),
        ("y_min", np.float32),
        ("dy", np.float32),
    ]
)

SHADER = """
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x_min: f32,
    dx: f32,
    y_min: f32,
    dy: f32,
};

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> escape: array<u32>;

@compute @workgroup_size(%d)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let idx = gid.x;
    if (idx >= p.width * p.height) {
        return;
    }
    let i = idx %% p.width;
    let j = idx / p.width;
    let cx = p.x_min + (f32(i) + 0.5) * p.dx;
    let cy = p.y_min + (f32(j) + 0.5) * p.dy;

    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    while (n < p.limit && zx * zx + zy * zy <= 4.0) {
        let t = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = t;
        n = n + 1u;
    }
    escape[idx] = n;
}
""" % WORKGROUP_SIZE


def read_parameters(path):
    with open(path, encoding="utf-8") as f:
        tokens = f.read().split()
    if len(tokens) < 7:
        raise ValueError(f"{path}: expected 7 values, found {len(tokens)}")
    width, height, limit = (int(t) for t in tokens[:3])
    x_min, x_max, y_min, y_max = (float(t) for t in tokens[3:7])
    if not (1 <= width <= 1024 and 1 <= height <= 1024):
        raise ValueError("width and height must be between 1 and 1024")
    if not (1 <= limit <= 1000):
        raise ValueError("limit must be between 1 and 1000")
    if not x_min < x_max or not y_min < y_max:
        raise ValueError("bounds must satisfy x_min < x_max and y_min < y_max")
    return width, height, limit, x_min, x_max, y_min, y_max


def request_device():
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    if adapter is None:
        adapter = wgpu.gpu.request_adapter_sync(force_fallback_adapter=True)
    if adapter is None:
        raise RuntimeError("no GPU adapter available")
    return adapter.request_device_sync()


def compute_escape_times(width, height, limit, x_min, x_max, y_min, y_max):
    """Run the escape-time kernel and return one escape count per grid point.

    The result is a flat array in row-major order: index j * width + i.
    """
    dx = (x_max - x_min) / width
    dy = (y_max - y_min) / height
    count = width * height

    params = np.zeros(1, dtype=PARAMS_DTYPE)
    params["width"] = width
    params["height"] = height
    params["limit"] = limit
    params["x_min"] = x_min
    params["dx"] = dx
    params["y_min"] = y_min
    params["dy"] = dy

    device = request_device()
    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "main"},
    )

    params_buffer = device.create_buffer_with_data(
        data=params.tobytes(), usage=wgpu.BufferUsage.UNIFORM
    )
    escape_buffer = device.create_buffer(
        size=count * 4,
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {
                "binding": 0,
                "resource": {"buffer": params_buffer, "offset": 0, "size": params_buffer.size},
            },
            {
                "binding": 1,
                "resource": {"buffer": escape_buffer, "offset": 0, "size": escape_buffer.size},
            },
        ],
    )

    encoder = device.create_command_encoder()
    compute_pass = encoder.begin_compute_pass()
    compute_pass.set_pipeline(pipeline)
    compute_pass.set_bind_group(0, bind_group)
    groups = math.ceil(count / WORKGROUP_SIZE)
    compute_pass.dispatch_workgroups(groups, 1, 1)
    compute_pass.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(escape_buffer, 0, count * 4)
    return np.frombuffer(data, dtype=np.uint32, count=count)


def summarize(escape, limit):
    """Return the output lines for an array of escape times."""
    inside = escape == limit
    escaped = escape[~inside].astype(np.int64)

    inside_count = int(np.count_nonzero(inside))
    bins = (8 * escaped) // limit
    bin_counts = np.bincount(bins, minlength=8)[:8]

    if escaped.size:
        mean = float(escaped.sum()) / escaped.size
    else:
        mean = 0.0

    lines = [f"INSIDE {inside_count}"]
    lines += [f"BIN {b} {int(bin_counts[b])}" for b in range(8)]
    lines.append(f"MEAN {mean:.3f}")
    return lines


def main(argv):
    if len(argv) != 2:
        print("usage: main.py <parameter-file>", file=sys.stderr)
        return 2
    try:
        width, height, limit, x_min, x_max, y_min, y_max = read_parameters(argv[1])
    except (OSError, ValueError) as err:
        print(f"error: {err}", file=sys.stderr)
        return 1

    escape = compute_escape_times(width, height, limit, x_min, x_max, y_min, y_max)
    for line in summarize(escape, limit):
        sys.stdout.write(line + "\n")
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

